H.background();
const a0 = P.a0, b = P.b, c = P.c;
const N = 9;
const seq = [a0];
for (let n = 1; n < N; n++) seq.push(b * seq[n - 1] + c);
let yLo = 0, yHi = 1;
for (let n = 0; n < N; n++) { yLo = Math.min(yLo, seq[n]); yHi = Math.max(yHi, seq[n]); }
const pad = (yHi - yLo) * 0.15 + 1;
const v = H.plot2d({ xMin: -0.5, xMax: N - 0.5, yMin: yLo - pad, yMax: yHi + pad });
v.grid(); v.axes();
const reveal = Math.min(N - 1, Math.floor((t * 0.7) % (N + 2)));
for (let n = 0; n <= reveal; n++) {
  if (n >= 1) v.arrow(n - 1, seq[n - 1], n, seq[n], { color: H.colors.good, width: 1.8, head: 7 });
  v.dot(n, seq[n], { r: 5, fill: n === 0 ? H.colors.violet : H.colors.accent });
}
v.circle(reveal, seq[reveal], 8 + 2 * Math.sin(t * 4), { fill: H.colors.warn });
H.text("Recursive:  a_n = b*a_(n-1) + c", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const prev = reveal === 0 ? a0 : seq[reveal - 1];
const step = reveal === 0 ? ("seed a_0 = " + a0.toFixed(1)) : ("a_" + reveal + " = " + b.toFixed(1) + "*" + prev.toFixed(1) + " + " + c.toFixed(1) + " = " + seq[reveal].toFixed(1));
H.text(step, 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "seed a_0", color: H.colors.violet }, { label: "computed a_n", color: H.colors.accent }], H.W - 200, 28);
